// === Tab: Area ===
class Area {
	constructor(pal) {
		this.pal = pal;
		this.objs = [];
		const pts = [
			createVector(0, 0),
			createVector(width, 0),
			createVector(width, height),
			createVector(0, height)
		];
		for (let i = 0; i < random(4); i++) pts.push(pts.shift());
		const p1 = pts[0];
		const p2 = pts[1];
		const p3 = pts[2];
		const p4 = pts[3];
		const p34 = p5.Vector.lerp(p3, p4, random(0.25, 0.75));

		let clrIdx;
		clrIdx = ~~random(this.pal.length);
		this.objs.push({p1: p1, p2: p2, p3: p34, clrIdx});
		clrIdx = ~~random(this.pal.length);
		this.objs.push({p1: p2, p2: p3, p3: p34, clrIdx});
		clrIdx = ~~random(this.pal.length);
		this.objs.push({p1: p34, p2: p4, p3: p1, clrIdx});
	} // constructor

	divide() {
		const randTriangle = random(this.objs); // this.objs[this.objs.length-1]

		var pts = [randTriangle.p1.copy(), randTriangle.p2.copy(), randTriangle.p3.copy()];
		shuffle(pts, true);

		var p1 = pts[0];
		var p2 = pts[1];
		var p3 = pts[2];
		const p23 = p5.Vector.lerp(p2, p3, random(0.25, 0.75));

		randTriangle.p1 = p1.copy();
		randTriangle.p2 = p2.copy();
		randTriangle.p3 = p23.copy();

		var clrIdx = ~~random(this.pal.length);
		this.objs.push({p1: p1.copy(), p2: p23.copy(), p3: p3.copy(), clrIdx});
	}	// devide

	show() {
		push();
		// blendMode(DIFFERENCE)
		noStroke();
		for (let o of this.objs) {
			let clr = color(this.pal[o.clrIdx]);
			// clr.setAlpha(128); fill(clr);
			stroke(clr); noFill();

			/*
			triangle(o.p1.x, o.p1.y, 
					 o.p2.x, o.p2.y,
					 o.p3.x, o.p3.y);
			*/

			var pts = [o.p1, o.p2, o.p3];
			let l1 = p5.Vector.dist(o.p2, o.p3);
			let l2 = p5.Vector.dist(o.p3, o.p1);
			let l3 = p5.Vector.dist(o.p1, o.p2);
			let dst = l1;
			if (l2 > l1 || l3 > l1) {
				if (l2 > l3) {
					dst = l2;
					pts = [o.p2, o.p3, o.p1];
				} else {
					dst = l3;
					pts = [o.p3, o.p1, o.p2];
				}
			}
			var p1 = pts[0].copy();
			var p2 = pts[1].copy();
			var p3 = pts[2].copy();

			const num = ~~(dst / 8);
			let svgStr = "";
			for (let i = 0; i < num; i++) {
				const f = i / num;
				// console.log(`num ${num} f ${nf(f, 0, 3)}`)
				const p = p5.Vector.lerp(p2, p3, f);
				line(p1.x, p1.y, p.x, p.y);
				svgStr += `<line x1="${nf(p1.x,0,3)}" y1="${nf(p1.y,0,3)}" x2="${nf(p.x,0,3)}" y2="${nf(p.y,0,3)}" />\n`;
			}

			const svgGr = `<g>\n${svgStr}</g>\n`
			SVG_GRPS[o.clrIdx].push(svgGr);
		}

		pop();
	} // show

} // class Area

