let area;

let NUM_SVG_GROUPS, SVG_GRPS;

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	describe('canvas with subdivided areas hatched vertically or horizontally');

	initArea();
	loop();
}

function initArea() {
	// https://blog.depositphotos.com/15-cyberpunk-color-palettes-for-dystopian-designs.html
	let palettes = [
		["#8386f5", "#3d43b4", "#04134b", "#083e12", "#1afe49"],
		["#f887ff", "#de004e", "#860029", "#321450", "#29132e"],
		["#e96d5e", "#ff9760", "#ffe69d", "#6a7e6a", "#393f5f"],
		["#ff124f", "#ff00a0", "#fe75fe", "#7a04eb", "#120458"],
		["#ff6e27", "#fbf665", "#73fffe", "#6287f8", "#383e65"],
		["#7700a6", "#fe00fe", "#defe47", "#00b3fe", "#0016ee"],
		["#63345e", "#ac61b9", "#b7c1de", "#0b468c", "#092047"],
		["#af43be", "#fd8090", "#c4ffff", "#08deea", "#1261d1"],
		["#a0ffe3", "#65dc98", "#8d8980", "#575267", "#222035"],
		["#ff2a6d", "#d1f7ff", "#f5d9e8", "#005678", "#01012b"],
		["#490109", "#d40011", "#fd7495", "#5e4ef8", "#14029a"],
		["#8f704b", "#daae6d", "#89e3f6", "#4d9e9b", "#44786a"],
		["#fff69f", "#fdd870", "#d0902f", "#a15501", "#351409"],
		["#b0acb0", "#e2dddf", "#85ebd9", "#3d898d", "#2f404d"],
		["#ff184c", "#ff577d", "#ffccdc", "#0a9cf5", "#003062"]
	]

	const randPal = random(palettes);
	area = new Area(randPal);

	NUM_SVG_GROUPS = randPal.length;
	SVG_GRPS = [];
	for (let i = 0; i < NUM_SVG_GROUPS; i++) SVG_GRPS[i] = [];

	for (let i = 0; i < random(3, 21); i++) area.divide();

	if (false) { // debug view 
		console.log(`----- area objs:`)
		for (let o of area.objs) {
			console.log(`${nf(o.p1.x,0,1)},${nf(o.p1.y,0,1)} ${nf(o.p2.x,0,1)},${nf(o.p2.y,0,1)} ${nf(o.p3.x,0,1)},${nf(o.p3.y,0,1)} ${area.pal[o.clrIdx]}`);
		}
	}
}

function draw() {
	background(160);

	// show all devided objs in area
	area.show();

	// noLoop() removed for animation
}

function windowResized() {
  setup();
}
function mousePressed() {
	if (mouseButton != RIGHT) {
		setup(); // if (isLooping()) // noLoop() removed for animation else loop();
	}
}

function keyPressed() {
	if (key === "s") {
		// console.log(key);

		let grStr = "";
		var clrIdx = 0;
		for (const gr of SVG_GRPS) {
			grStr += `<g stroke="${area.pal[clrIdx++]}" fill="none">\n`;
			for (const el of gr) {
				grStr += `${el}\n`;
			}
			grStr += `</g>\n`;
		}
		var svgStr = `<svg width="${width}" height="${height}" xmlns="http://www.w3.org/2000/svg">\n${grStr}\n</svg>`;
		// console.log(svgStr)
		save(svgStr.split("\n"), "epi_hatched_triangles.svg.txt")

	}
}

function mRand(v1, v2) {
	const vd = (v2 - v1);
	return floor(v1 + random(vd * 0.3, vd * 0.7))
}
function mFract(v1, v2, f) {
	var vd = (v2 - v1);
	return floor(v1 + vd * f);
}
